pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val, uint256 val2) internal {
        bool firstReverted;
        try c.SetMinSum(val) { firstReverted = false; } catch { firstReverted = true; }
        uint256 minSumAfterFirst;
        try c.MinSum() returns (uint256 __r) { minSumAfterFirst = __r; } catch { return; }
        bool secondReverted;
        try c.SetMinSum(val2) { secondReverted = false; } catch { secondReverted = true; }
        uint256 minSumAfterSecond;
        try c.MinSum() returns (uint256 __r) { minSumAfterSecond = __r; } catch { return; }
        assertTrue(firstReverted == false && minSumAfterFirst == val && secondReverted == false && minSumAfterSecond == val2);
    }

    function testFuzz_run(uint256 val, uint256 val2) public {
        _run(val, val2);
    }

    receive() external payable {}
}
